const requester = $input.first().json;
if (!requester.id || !requester.active) throw new Error('Invalid session.');
if (requester.role !== 'admin') throw new Error('Only an admin can manage discount cards.');
const body = $('Webhook: save-discount-card').first().json.body || {};
const id = body.id ? parseInt(body.id, 10) : null;
if (body.id && !Number.isInteger(id)) throw new Error('"id" must be an integer.');
const name = (typeof body.name === 'string' ? body.name : '').replace(/[\u0000-\u001f\u007f]/g, ' ').replace(/\s+/g, ' ').trim();
if (!name) throw new Error('Give this discount card a name.');
if (name.length > 60) throw new Error('The name is too long (maximum 60 characters).');
const percent = Number(body.percent);
if (!Number.isFinite(percent) || percent <= 0 || percent > 100) throw new Error('The discount must be more than 0 and at most 100 percent.');
const isActive = body.is_active === false || body.is_active === 'false' ? false : true;
return [{ json: { id, name, percent: Math.round(percent * 100) / 100, isActive } }];

