const body = $('Webhook: confirm-event-billing').first().json.body || {};
const eventId = parseInt(body.event_id, 10);
if (!Number.isInteger(eventId)) throw new Error('"event_id" must be an integer.');
const int = (v, name) => { if (v === null || v === undefined || v === '') return null; const n = parseInt(v, 10); if (!Number.isInteger(n)) throw new Error('"' + name + '" must be an integer.'); return n; };
const card = int(body.discount_card_id, 'discount_card_id');
const pkg = int(body.client_package_id, 'client_package_id');
const mem = int(body.client_membership_id, 'client_membership_id');
const mode = body.membership_mode === 'session' || body.membership_mode === 'discount' ? body.membership_mode : null;
return [{ json: { eventId, card, pkg, mem, mode, userId: requester.id, isAdmin: requester.role === 'admin', unconfirm: body.unconfirm === true || body.unconfirm === 'true' } }];

