const requester = $input.first().json;
if (!requester.id || !requester.active) throw new Error('Invalid session.');
const q = $('Webhook: get-commission-report').first().json.query || {};
const ok = (v) => /^\d{4}-\d{2}-\d{2}$/.test(String(v || ''));
if (!ok(q.start) || !ok(q.end)) throw new Error('Choose a start and end date.');
if (q.start > q.end) throw new Error('The start date must be before the end date.');
return [{ json: { start: q.start, end: q.end, userId: requester.id, isAdmin: requester.role === 'admin' } }];

